import time
import asyncio


class CircuitBreaker:
    def __init__(self, failure_threshold=5, reset_timeout_ms=30000):
        self.state = "CLOSED"
        self.failure_count = 0
        self.failure_threshold = failure_threshold
        self.reset_timeout_ms = reset_timeout_ms
        self.opened_at = None

    def record_success(self):
        self.failure_count = 0
        self.state = "CLOSED"

    def record_failure(self):
        self.failure_count += 1
        if self.state == "HALF_OPEN" or self.failure_count >= self.failure_threshold:
            self.state = "OPEN"
            self.opened_at = time.time() * 1000
            self.failure_count = 0

    def can_attempt(self):
        if self.state == "CLOSED":
            return True
        if self.state == "OPEN":
            elapsed = time.time() * 1000 - self.opened_at
            if elapsed >= self.reset_timeout_ms:
                self.state = "HALF_OPEN"
                return True
            return False
        return True


async def call_through_breaker(breaker, fn, fallback=None):
    if not breaker.can_attempt():
        if fallback:
            return await fallback()
        raise RuntimeError("Circuit is open, call rejected without attempting it")

    try:
        result = await fn()
        breaker.record_success()
        return result
    except Exception as err:
        breaker.record_failure()
        raise err


async def risky_call():
    raise RuntimeError("downstream timeout")


async def fallback_call():
    return {"cached": True}


async def demo():
    breaker = CircuitBreaker(failure_threshold=1)

    try:
        result = await call_through_breaker(breaker, risky_call, fallback_call)
        print(f"first call result: {result}")
    except Exception as err:
        print(f"first call error: {err}")

    result = await call_through_breaker(breaker, risky_call, fallback_call)
    print(f"second call result: {result} state={breaker.state}")


if __name__ == "__main__":
    asyncio.run(demo())

