import java.util.Map;
import java.util.concurrent.Callable;
import java.util.function.Supplier;

class CircuitBreaker {
    private String state = "CLOSED";
    private int failureCount = 0;
    private final int failureThreshold;
    private final long resetTimeoutMs;
    private long openedAt = 0;

    public CircuitBreaker(int failureThreshold, long resetTimeoutMs) {
        this.failureThreshold = failureThreshold;
        this.resetTimeoutMs = resetTimeoutMs;
    }

    public void recordSuccess() {
        this.failureCount = 0;
        this.state = "CLOSED";
    }

    public void recordFailure() {
        this.failureCount++;
        if (state.equals("HALF_OPEN") || failureCount >= failureThreshold) {
            this.state = "OPEN";
            this.openedAt = System.currentTimeMillis();
            this.failureCount = 0;
        }
    }

    public boolean canAttempt() {
        if (state.equals("CLOSED")) return true;
        if (state.equals("OPEN")) {
            long elapsed = System.currentTimeMillis() - openedAt;
            if (elapsed >= resetTimeoutMs) {
                state = "HALF_OPEN";
                return true;
            }
            return false;
        }
        return true;
    }

    public String getState() {
        return state;
    }
}

class BreakerCaller {
    public <T> T callThroughBreaker(CircuitBreaker breaker, Callable<T> fn, Supplier<T> fallback) throws Exception {
        if (!breaker.canAttempt()) {
            if (fallback != null) return fallback.get();
            throw new IllegalStateException("Circuit is open, call rejected without attempting it");
        }

        try {
            T result = fn.call();
            breaker.recordSuccess();
            return result;
        } catch (Exception err) {
            breaker.recordFailure();
            throw err;
        }
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        CircuitBreaker breaker = new CircuitBreaker(1, 30000);
        BreakerCaller caller = new BreakerCaller();

        Callable<Map<String, Object>> riskyCall = () -> {
            throw new RuntimeException("downstream timeout");
        };
        Supplier<Map<String, Object>> fallbackCall = () -> Map.of("cached", true);

        try {
            Map<String, Object> result = caller.callThroughBreaker(breaker, riskyCall, fallbackCall);
            System.out.println("first call result: " + result);
        } catch (Exception err) {
            System.out.println("first call error: " + err.getMessage());
        }

        Map<String, Object> result = caller.callThroughBreaker(breaker, riskyCall, fallbackCall);
        System.out.println("second call result: " + result + " state=" + breaker.getState());
    }
}

