#include <iostream>
#include <string>
#include <functional>
#include <stdexcept>
#include <chrono>
#include <thread>

class CircuitBreaker {
public:
    CircuitBreaker(int failureThreshold, long long resetTimeoutMs)
        : state("CLOSED"), failureCount(0), failureThreshold(failureThreshold),
          resetTimeoutMs(resetTimeoutMs), openedAt(0) {}

    void recordSuccess() {
        failureCount = 0;
        state = "CLOSED";
    }

    void recordFailure() {
        failureCount++;
        if (state == "HALF_OPEN" || failureCount >= failureThreshold) {
            state = "OPEN";
            openedAt = currentMillis();
            failureCount = 0;
        }
    }

    bool canAttempt() {
        if (state == "CLOSED") return true;
        if (state == "OPEN") {
            long long elapsed = currentMillis() - openedAt;
            if (elapsed >= resetTimeoutMs) {
                state = "HALF_OPEN";
                return true;
            }
            return false;
        }
        return true;
    }

    std::string getState() const {
        return state;
    }

private:
    static long long currentMillis() {
        using namespace std::chrono;
        return duration_cast<milliseconds>(system_clock::now().time_since_epoch()).count();
    }

    std::string state;
    int failureCount;
    int failureThreshold;
    long long resetTimeoutMs;
    long long openedAt;
};

struct InventoryResult {
    bool cached = false;
    std::string itemId;
    bool inStock = false;
};

std::ostream& operator<<(std::ostream& os, const InventoryResult& r) {
    if (r.cached) {
        os << "{inStock=null, cached=true}";
    } else {
        os << "{itemId=" << r.itemId << ", inStock=" << (r.inStock ? "true" : "false") << "}";
    }
    return os;
}

template <typename T>
T callThroughBreaker(CircuitBreaker& breaker, const std::function<T()>& fn, const std::function<T()>& fallback) {
    if (!breaker.canAttempt()) {
        if (fallback) return fallback();
        throw std::runtime_error("Circuit is open, call rejected without attempting it");
    }

    try {
        T result = fn();
        breaker.recordSuccess();
        return result;
    } catch (const std::exception&) {
        breaker.recordFailure();
        throw;
    }
}

InventoryResult flakyInventoryService(int callIndex) {
    // fails for calls 3 through 7, recovers after that
    if (callIndex >= 3 && callIndex <= 7) {
        throw std::runtime_error("inventory service timeout");
    }
    InventoryResult r;
    r.itemId = "sku-42";
    r.inStock = true;
    return r;
}

int main() {
    CircuitBreaker breaker(3, 2000);

    for (int i = 1; i <= 10; i++) {
        std::function<InventoryResult()> risky = [i]() { return flakyInventoryService(i); };
        std::function<InventoryResult()> fallback = []() {
            InventoryResult r;
            r.cached = true;
            return r;
        };

        try {
            InventoryResult result = callThroughBreaker<InventoryResult>(breaker, risky, fallback);
            std::cout << "call " << i << ": state=" << breaker.getState() << " result=" << result << std::endl;
        } catch (const std::exception& err) {
            std::cout << "call " << i << ": state=" << breaker.getState() << " error=" << err.what() << std::endl;
        }
        if (i == 8) std::this_thread::sleep_for(std::chrono::milliseconds(2100));
    }

    return 0;
}
